function strictDollarAmount(value){
 const text=String(value??'').trim();
 if(!/^\d+(?:\.\d{1,2})?$/.test(text))throw new Error('Amount must contain digits and at most two decimal places. Letters, e notation, and signs are not accepted.');
 const amount=Number(text),cents=Math.round(amount*100);
 if(!Number.isFinite(amount)||amount<=0||!Number.isSafeInteger(cents))throw new Error('Enter a positive dollar amount within the supported range.');
 return amount;
}
function editableValues(row,data,unlocked=!!editState?.detailsUnlocked){
 return {amount:unlocked?strictDollarAmount(data.get('amount')):Number(row.amount),counterparty:unlocked?String(data.get('counterparty')||'').trim():String(row.counterparty||''),description:unlocked?String(data.get('description')||'').trim():String(row.description||''),payment_method:String(data.get('payment_method')||'unspecified'),evidence_ref:String(data.get('evidence_ref')||'').trim(),review_status:String(data.get('review_status')||'')};
}
function fieldDisplay(key,value){return key==='amount'?money(value):key==='payment_method'?(PAYMENT_METHODS[value]||value):key==='review_status'?(REVIEW_LABELS[value]||value):String(value||'Not recorded');}
function stageCorrection(values,reason,approval=null){
 if(!editState||correctionBusy)return;
 const row=editState.base;
 try{
  if(!Number.isFinite(values.amount)||values.amount<=0||Math.abs(values.amount*100-Math.round(values.amount*100))>0.00001)throw new Error('Use a positive dollar amount with at most two decimal places.');
  values.amount=Number(values.amount.toFixed(2));
  if(!values.description)throw new Error('A purpose is required.');
  if(!Object.hasOwn(PAYMENT_METHODS,values.payment_method))throw new Error('Choose a listed payment method.');
  if(!approval&&!['unreviewed','accountant_review','ready'].includes(values.review_status))throw new Error('Choose Unreviewed, Needs accountant review, or Ready for accountant. Approval has a separate workflow.');
  if(values.review_status==='ready'&&(!values.evidence_ref||values.payment_method==='unspecified'))throw new Error('Ready for accountant requires a payment method and a safe payment reference.');
  if(String(reason||'').trim().length<3)throw new Error('Explain the correction in the reason field.');
  const fields=EDIT_FIELDS.filter(key=>String(values[key])!==String(row[key]??''));
  if(approval)fields.push('accountant_approval');
  if(!fields.length)throw new Error('Nothing changed. Cancel to leave the ledger untouched.');
  if(['amount','counterparty','description'].some(key=>String(values[key])!==String(row[key]??'')))editState.detailsUnlocked=true;
  editState.values={...values};editState.reason=reason.trim();
  pendingCorrection={values:{...values},reason:reason.trim(),fields,approval,rootId:row.root_entry_id,expectedRevision:row.current_revision_id,baseSignature:stableString(row),entryId:uid(),submissionId:uid(),record:null};
  renderCorrectionPreview();
  settleTouchWorkspace();
 }catch(error){ledgerNotice(String(error?.message||error));}
}
function renderCorrectionPreview(){
 const pending=pendingCorrection;if(!editState||!pending)return;
 const row=editState.base,delta=Math.round(pending.values.amount*100)-Math.round(row.amount*100),amountNotice=delta===0?'Amount unchanged. One history correction; no new payment.':`Amount changes by ${money(delta/100)}. The current ${row.entry_type==='income'?'Money In':row.entry_type==='expense'?'Money Out':'transaction amount'} will change; the original amount stays in history.`;
 const changed=pending.fields.filter(key=>key!=='accountant_approval').map(key=>`<div class="tax-change-row"><b>${safe(EDIT_LABELS[key])}</b><span><small>CURRENT</small>${safe(key==='review_status'?reviewLabel(row):fieldDisplay(key,row[key]))}</span><span><small>AFTER CONFIRMATION</small>${safe(fieldDisplay(key,pending.values[key]))}</span></div>`).join('');
 const approval=pending.approval?`<div class="tax-approval-warning"><b>Operator-recorded accountant approval</b><p>Accountant: ${safe(pending.approval.accountant_name)} · Date: ${safe(pending.approval.reviewed_on)}</p><p>Evidence reference: ${safe(pending.approval.evidence_ref)}</p><p>Applies to revision <code>${safe(pending.expectedRevision)}</code>. The app has not independently verified this approval.</p></div>`:'';
 el('taxCorrectionPanel').innerHTML=`<header><div><small>PREVIEW · NOT YET SAVED</small><h3>${pending.approval?'Confirm the approval evidence':'Confirm the exact changes'}</h3></div><button type="button" data-correction-cancel>CANCEL</button></header>${editorIdentity()}<p id="taxCorrectionNotice" class="authority-ledger-status" role="status">${safe(amountNotice)}</p><div class="tax-change-list">${changed}</div>${approval}<p class="tax-correction-reason"><b>Reason</b> ${safe(pending.reason)}</p><p class="tax-correction-boundary">Original ID and existing history are unchanged. This saves one new correction to this book only.</p><div class="tax-correction-buttons"><button type="button" data-correction-edit>EDIT CHANGES</button><button id="taxConfirmCorrection" type="button" class="tax-correction-primary">${pending.approval?'CONFIRM APPROVAL RECORD':'CONFIRM CORRECTION'}</button></div>`;
}
async function confirmCorrection(){
 if(!editState||!pendingCorrection||correctionBusy)return;
 const context=editState,pending=pendingCorrection,button=el('taxConfirmCorrection');
 correctionBusy=true;if(button){button.disabled=true;button.textContent='VERIFYING SAVE…';}ledgerNotice('Verifying one correction. Please wait; do not create another payment.');
 try{
  if(el('taxEntity').value!==context.key||Number(el('taxYear').value)!==context.year||office!==context.office)throw new Error('The active book or office changed. Cancel and reopen this record.');
  const authority=await requireLedgerAuthority(context.key,context.office),book=await idbRead(ledgerDb);bookCache=cloneBook(book);
  let already=book.entries.find(item=>item.entry_id===pending.entryId);
  if(already){if(!pending.record||stableString(already)!==stableString(pending.record))throw new Error('A record identity conflict was blocked.');}
  else{
   const current=currentForRoot(book,pending.rootId,context.key);
   if(!current||current.current_revision_id!==pending.expectedRevision||stableString(current)!==pending.baseSignature)throw new Error('This record changed since your preview. Cancel and reopen Correct record to inspect the latest values. No correction was saved.');
   const timestamp=new Date(Math.max(Date.now(),(Date.parse(current.created_at)||0)+1)).toISOString();
   const raw=book.entries.find(item=>item.entry_id===current.current_revision_id);
   const correction={...raw,...pending.values,...authority,entry_id:pending.entryId,submission_id:pending.submissionId,record_kind:'correction',correction_of:pending.rootId,previous_revision_id:pending.expectedRevision,correction_reason:pending.reason,correction_fields:pending.fields,created_at:timestamp,recorded_in_build:BUILD,source:'BROWSER BOOK',accountant_approval:pending.approval?{...pending.approval,approved_revision_id:pending.expectedRevision,recorded_by_office:context.office,recorded_at:timestamp,verification:'operator_attestation_not_independently_verified'}:null};
   delete correction.root_entry_id;delete correction.current_revision_id;delete correction.revision_count;delete correction.recovery_source;
   pending.record=correction;book.entries.push(correction);await writeBooks(book);
   already=readBooks().entries.find(item=>item.entry_id===pending.entryId);
   if(!already||stableString(already)!==stableString(correction))throw new Error('Correction read-back did not match. Reopen the book before retrying.');
  }
  const origin=context.origin,root=context.rootId,title=context.base.description;
  correctionBusy=false;clearEditor();checkQueueOpen=origin==='queue';renderTax();
  ledgerNotice(`${pending.approval?'Approval attestation':'Correction'} verified: ${title}. One history record saved; no new payment. Original identity preserved.`,true);
  requestAnimationFrame(()=>{if(origin==='queue')el('taxCheckQueue')?.scrollIntoView({block:'start',behavior:'auto'});else document.querySelector(`[data-record-root="${CSS.escape(root)}"]`)?.scrollIntoView({block:'center',behavior:'auto'});});
 }catch(error){
  correctionBusy=false;ledgerNotice(String(error?.message||error));
  if(button){button.disabled=false;button.textContent=error?.code==='SAVE_UNVERIFIED'?'RECHECK SAVED CORRECTION':pending.approval?'CONFIRM APPROVAL RECORD':'CONFIRM CORRECTION';}
 }finally{correctionBusy=false;}
}
function historySnapshot(book,key,year){
 const scoped=book.entries.filter(row=>row.entity_key===key),idSet=new Set();
 for(const row of scoped){if(idSet.has(row.entry_id))throw new Error('Duplicate history identities prevent a trustworthy export.');idSet.add(row.entry_id);}
 for(const row of scoped)if(row.correction_of&&!scoped.some(root=>!root.correction_of&&root.entry_id===row.correction_of))throw new Error('An orphaned correction needs review before this book can be exported.');
 const roots=scoped.filter(row=>!row.correction_of&&String(row.transaction_date).slice(0,4)===String(year)),rows=currentRows(book,key,year),entity=entities().find(row=>row.key===key);
 const transactions=roots.map(root=>{const revisions=revisionsFor(book,root);let previous=root.entry_id;
  const lineage=revisions.map(revision=>{if(revision.previous_revision_id&&revision.previous_revision_id!==previous)throw new Error('A branched correction chain needs review before export.');const link={entry_id:revision.entry_id,previous_revision_id:revision.previous_revision_id||previous,link_source:revision.previous_revision_id?'recorded':'inferred_legacy_order'};previous=revision.entry_id;return link;});
  return {root_entry_id:root.entry_id,current_revision_id:previous,original:root,corrections:revisions,lineage};
 });
 const cents=type=>rows.filter(row=>row.entry_type===type).reduce((sum,row)=>sum+Math.round(Number(row.amount)*100),0);
 return {schema:'dark-sky-book-history-v1',build:BUILD,exported_at:new Date().toISOString(),scope:{entity_key:key,entity_name:entity?.name||key,entity_type:entity?.type||'',tax_year:year,accounting_method:book.methods[key]||'cash',storage:'BROWSER BOOK',server_backup_verified:false,selection_rule:'Original transaction year; every revision of those originals is included.'},transaction_count:roots.length,history_record_count:transactions.reduce((sum,item)=>sum+1+item.corrections.length,0),summary_cents:{money_in:cents('income'),money_out:cents('expense'),what_remains:cents('income')-cents('expense')},warning:'Correction amounts are replacement snapshots, not extra payments. Do not sum all historical amounts. This is an export, not proof of cloud backup or a tested restore.',transactions};
}
function downloadLedgerFile(name,content,type){
 const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');
 a.href=url;a.download=name;a.hidden=true;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
async function exportBook(kind){
 const button=el(kind==='csv'?'taxExportCsv':'taxExportHistory');if(button?.disabled||editState||correctionBusy)return;
 const label=button?.textContent;if(button){button.disabled=true;button.textContent='PREPARING…';}
 try{
  const key=el('taxEntity').value,year=Number(el('taxYear').value),book=await freshBookSnapshot(key),payload=historySnapshot(book,key,year),rows=currentRows(book,key,year),name=String(payload.scope.entity_name).toLowerCase().replace(/[^a-z0-9]+/g,'-'),stamp=payload.exported_at.replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z');
  if(key!==el('taxEntity').value||year!==Number(el('taxYear').value))throw new Error('Book selection changed. Export again from the intended book.');
  if(kind==='csv'){
   const headers=['entity_key','entity_name','entity_type','tax_year','accounting_method','transaction_date','entry_type','category_code','category_label','amount_usd','counterparty','description','payment_method','payment_reference','review_status','acting_office','source','created_at','root_entry_id','current_revision_id','revision_count','original_created_at','approval_basis','export_kind'];
   const csv=[headers.map(csvCell).join(','),...rows.map(row=>{const root=book.entries.find(item=>item.entry_id===row.root_entry_id);return [row.entity_key,row.entity_name,row.entity_type,year,payload.scope.accounting_method,row.transaction_date,row.entry_type,row.category_code,row.category_label,Number(row.amount).toFixed(2),row.counterparty,row.description,row.payment_method||'unspecified',row.evidence_ref,row.review_status,row.acting_office,row.source,row.created_at,row.root_entry_id,row.current_revision_id,row.revision_count,root?.created_at||'',row.review_status==='approved'?(row.accountant_approval?.attested?'operator_attestation_not_independently_verified':'legacy_selection_not_verified'):'not_approved','current_transaction_summary'].map(csvCell).join(',');})].join('\r\n');
   downloadLedgerFile(`${name}-${year}-accountant-ledger-${stamp}.csv`,'\uFEFF'+csv,'text/csv;charset=utf-8');
   ledgerNotice(`Prepared ${rows.length} current transactions for ${payload.scope.entity_name} (${year}). Corrections are not extra income. Confirm the browser download to keep the CSV.`,true);
  }else{
   const serialized=JSON.stringify(payload),digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(serialized)),sha=[...new Uint8Array(digest)].map(value=>value.toString(16).padStart(2,'0')).join('');
   assertLocalSession(office==='admiral'?'admiral':'captain');if(key!==el('taxEntity').value||year!==Number(el('taxYear').value))throw new Error('Book selection changed during export. No file was prepared.');
   const envelope={format:'dark-sky-full-history-export-v1',integrity:{algorithm:'SHA-256',serialization:'UTF-8 of JSON.stringify(payload), preserving exported key order',sha256:sha},payload};
   downloadLedgerFile(`${name}-${year}-full-history-${stamp}.json`,JSON.stringify(envelope,null,2),'application/json;charset=utf-8');
   ledgerNotice(`Prepared full history: ${payload.transaction_count} transactions and ${payload.history_record_count} original/correction records for ${payload.scope.entity_name} (${year}). Raw values preserved. Confirm the browser download.`,true);
  }
 }catch(error){ledgerNotice(`Export stopped. ${String(error?.message||error)}`);}
 finally{if(button){button.disabled=false;button.textContent=label;}}
}
// Recovery merges with a fresh durable read in the same transaction, so an older tab cannot erase a newly appended correction.
async function atomicRecoveryMerge(db,proposed){
 const expected=await new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite'),store=tx.objectStore(DB_STORE);let result,failure;
  const req=store.get('current');req.onsuccess=()=>{try{const fresh=cleanBook(req.result||{}),map=new Map(fresh.entries.map(row=>[row.entry_id,row]));for(const row of proposed.entries)if(!map.has(row.entry_id))map.set(row.entry_id,row);result=cleanBook({methods:{...proposed.methods,...fresh.methods},entries:[...map.values()]});store.put(result,'current');const verify=store.get('current');verify.onsuccess=()=>{if(stableString(cleanBook(verify.result))!==stableString(result)){failure=new Error('Recovery read-back did not match.');tx.abort();}};}catch(error){failure=error;tx.abort();}};
  tx.oncomplete=()=>resolve(result);tx.onabort=()=>reject(failure||tx.error||new Error('Recovery write was interrupted.'));tx.onerror=()=>{failure=failure||tx.error;};
 });
 const verified=await idbRead(db),actual=new Map(verified.entries.map(row=>[row.entry_id,row]));if(expected.entries.some(row=>stableString(actual.get(row.entry_id))!==stableString(row)))throw new Error('Recovered history could not be verified.');return verified;
}
